/* ─── Magic Pen's service worker ─────────────────────────────────────────────
 *
 * The app is for three-to-six-year-olds, and the places they use it are cars,
 * planes, waiting rooms and grandparents' houses with the wifi password on a
 * fridge nobody can find. Until this file existed, none of that worked: the app
 * would not open at all without a network, even though everything it needs —
 * every world, every lesson, every doodle — was already local.
 *
 * Nothing here is generated by a bundler plugin. It is small enough to read in
 * one sitting, and the caching rules are decisions rather than defaults.
 *
 * ── the three kinds of thing this app serves ──
 *
 *   1. The shell — index.html, every hashed JS/CSS chunk, the two fonts, the
 *      icons. PRECACHED on install, so the very first time a child is offline
 *      the whole app opens and every world works. About 1.3MB.
 *
 *   2. The voice — 356 clips under /voice/clips, hash-named and immutable.
 *      NOT precached: that is 5MB, and downloading it on a parent's mobile data
 *      before they have decided they like the app is rude. They are cached
 *      as they are played, so any lesson a child has done once speaks offline
 *      forever, and anything unheard falls back to the browser's own voice —
 *      which is exactly what that fallback was built for.
 *
 *   3. The API — /api/*. NEVER cached, never intercepted. It is the one thing
 *      that talks to the network, it is opt-in, and a stale answer there would
 *      be worse than no answer.
 *
 * ── why this does not call skipWaiting ──
 * A new worker waits until every tab of the app is closed before it takes over.
 * Taking over mid-session would swap the hashed chunks under a running app, and
 * a lazy chunk that no longer exists is a blank screen — in the middle of a
 * child's drawing. Waiting costs one relaunch and cannot do that.
 */

const VERSION = "__VERSION__";
const SHELL_CACHE = `magicpen-shell-${VERSION}`;
const MEDIA_CACHE = "magicpen-media-v1";   // voice clips: content-hashed, so one cache forever

/** Everything the app needs to open and run with no network at all. */
const PRECACHE = __PRECACHE__;

/* ── install: lay the shell down ──────────────────────────────────────────── */

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then(async (cache) => {
      /* One at a time rather than cache.addAll: addAll rejects the whole install
         if a single file 404s, which would leave a child with no offline app
         because of one stale filename. A missing file is worth a warning, not a
         failed install. */
      await Promise.all(
        PRECACHE.map((url) =>
          cache.add(new Request(url, { cache: "reload" })).catch(() => {
            /* skipped: the app still works, this one asset just won't be offline */
          }),
        ),
      );
    }),
  );
});

/* ── activate: sweep up the last version's shell ──────────────────────────── */

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys.map((k) => {
          // keep this version's shell and the media cache; bin older shells
          if (k === SHELL_CACHE || k === MEDIA_CACHE) return undefined;
          if (k.startsWith("magicpen-")) return caches.delete(k);
          return undefined;
        }),
      );
      // a navigation can be served from cache the moment this worker is live
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable().catch(() => {});
      }
      await self.clients.claim();
    })(),
  );
});

/* ── fetch ────────────────────────────────────────────────────────────────── */

/** Content-hashed and therefore safe to keep forever. */
function isImmutable(url) {
  return (
    url.pathname.startsWith("/assets/") ||     // vite's hashed chunks
    url.pathname.startsWith("/fonts/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname.startsWith("/voice/clips/") ||   // sha1-named voice clips
    url.pathname.startsWith("/sounds/clips/")    // hash-named creature sounds
  );
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  // only keep a real answer; an opaque or failed one would poison the cache
  if (res && res.ok && res.status === 200) cache.put(request, res.clone());
  return res;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;   // never touch anything off-origin
  if (url.pathname.startsWith("/api/")) return;      // the one live thing: leave it alone

  /* A page. Network first so a deploy is picked up the moment there is a
     network, cache second so a plane is not a blank screen. Falls back to the
     app shell for any in-app URL, which is what a single-page app needs. */
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const preload = await event.preloadResponse;
          const res = preload || (await fetch(request));
          const cache = await caches.open(SHELL_CACHE);
          if (res && res.ok) cache.put(request, res.clone());
          return res;
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          return (
            (await cache.match(request)) ||
            (await cache.match("/index.html")) ||
            (await cache.match("/")) ||
            Response.error()
          );
        }
      })(),
    );
    return;
  }

  // a clip, a chunk, a font, an icon — named by its content, so keep it
  if (isImmutable(url)) {
    const media = url.pathname.startsWith("/voice/clips/") || url.pathname.startsWith("/sounds/clips/");
    const cacheName = media ? MEDIA_CACHE : SHELL_CACHE;
    event.respondWith(cacheFirst(request, cacheName).catch(() => caches.match(request).then((r) => r || Response.error())));
    return;
  }

  /* Everything else same-origin — the voice manifest, privacy.html. Fresh when
     there is a network, and still there when there is not. */
  event.respondWith(
    (async () => {
      try {
        const res = await fetch(request);
        if (res && res.ok) {
          const cache = await caches.open(SHELL_CACHE);
          cache.put(request, res.clone());
        }
        return res;
      } catch {
        const hit = await caches.match(request);
        if (hit) return hit;
        throw new Error("offline and not cached");
      }
    })(),
  );
});
